import { describe, it, expect, beforeEach } from 'vitest'
import { db } from '@/db/index.js'
import { users } from '@/db/schema.js'
import { createUser, getUserById, updateUser, StaffNotFoundError } from '../users.service.js'

describe('Staff Member Service — CRUD', () => {
  async function resetData() {
    await db.delete(users)
  }

  beforeEach(async () => {
    await resetData()
  })

  // ---------------------------------------------------------------------------
  // getUserById
  // ---------------------------------------------------------------------------

  describe('getUserById', () => {
    it('should return a staff member by ID', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
      })

      const found = await getUserById(created.id)

      expect(found.id).toBe(created.id)
      expect(found.name).toBe('Jan Kowalski')
      expect(found.role).toBe('mechanic')
      expect(found.hourlyRate).toBe(4500)
      expect(found.isActive).toBe(true)
    })

    it('should throw StaffNotFoundError for non-existent ID', async () => {
      const fakeId = '00000000-0000-0000-0000-000000000000'

      await expect(getUserById(fakeId)).rejects.toThrow(StaffNotFoundError)
      await expect(getUserById(fakeId)).rejects.toThrow(
        /Staff member not found: ${fakeId}/
      )
    })
  })

  // ---------------------------------------------------------------------------
  // updateUser — partial updates
  // ---------------------------------------------------------------------------

  describe('updateUser', () => {
    it('should update name only and return updated record', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
      })

      const updated = await updateUser(created.id, {
        name: 'Jan Nowak',
      })

      expect(updated.name).toBe('Jan Nowak')
      expect(updated.role).toBe('mechanic') // unchanged
      expect(updated.hourlyRate).toBe(4500) // unchanged
      expect(updated.isActive).toBe(true) // unchanged
    })

    it('should update role only', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
      })

      const updated = await updateUser(created.id, {
        role: 'manager',
      })

      expect(updated.role).toBe('manager')
      expect(updated.name).toBe('Jan Kowalski') // unchanged
    })

    it('should update hourlyRate only', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
      })

      const updated = await updateUser(created.id, {
        hourlyRate: 5500,
      })

      expect(updated.hourlyRate).toBe(5500)
    })

    it('should toggle isActive to false (soft delete)', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
      })

      expect(created.isActive).toBe(true)

      const updated = await updateUser(created.id, {
        isActive: false,
      })

      expect(updated.isActive).toBe(false)
    })

    it('should toggle isActive back to true (reactivate)', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
        isActive: false,
      })

      expect(created.isActive).toBe(false)

      const updated = await updateUser(created.id, {
        isActive: true,
      })

      expect(updated.isActive).toBe(true)
    })

    it('should update multiple fields at once', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
      })

      const updated = await updateUser(created.id, {
        name: 'Anna Nowak',
        role: 'manager',
        hourlyRate: 6000,
      })

      expect(updated.name).toBe('Anna Nowak')
      expect(updated.role).toBe('manager')
      expect(updated.hourlyRate).toBe(6000)
    })

    it('should throw StaffNotFoundError for non-existent ID', async () => {
      const fakeId = '00000000-0000-0000-0000-000000000000'

      await expect(
        updateUser(fakeId, { name: 'Nobody' })
      ).rejects.toThrow(StaffNotFoundError)
    })

    it('should reject empty payload (no fields provided)', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
      })

      // updateStaffMemberSchema requires at least one field via .refine()
      await expect(
        updateUser(created.id, {})
      ).rejects.toThrow()
    })

    it('should reject invalid role value', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
      })

      // @ts-expect-error — testing runtime validation of invalid enum
      await expect(
        updateUser(created.id, { role: 'supervisor' })
      ).rejects.toThrow()
    })

    it('should reject negative hourlyRate', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
      })

      await expect(
        updateUser(created.id, { hourlyRate: -100 })
      ).rejects.toThrow()
    })

    it('should reject non-integer hourlyRate', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
      })

      await expect(
        updateUser(created.id, { hourlyRate: 45.5 })
      ).rejects.toThrow()
    })

    it('should reject empty name string', async () => {
      const created = await createUser({
        name: 'Jan Kowalski',
        role: 'mechanic',
        hourlyRate: 4500,
      })

      await expect(
        updateUser(created.id, { name: '' })
      ).rejects.toThrow()
    })
  })
})

