        body: JSON.stringify({ name: 'Jan Nowak' }),
      })

      expect(res.status).toBe(200)

      const body = await res.json() as Record<string, unknown>
      expect(body.name).toBe('Jan Nowak')
      expect(body.role).toBe('mechanic') // unchanged
      expect(body.hourlyRate).toBe(4500) // unchanged
    })

    it('should update role', async () => {
      const res = await app.request(`/api/users/${userId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ role: 'manager' }),
      })

      expect(res.status).toBe(200)

      const body = await res.json() as Record<string, unknown>
      expect(body.role).toBe('manager')
    })

    it('should update hourlyRate', async () => {
      const res = await app.request(`/api/users/${userId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ hourlyRate: 5500 }),
      })

      expect(res.status).toBe(200)

      const body = await res.json() as Record<string, unknown>
      expect(body.hourlyRate).toBe(5500)
    })

    it('should toggle isActive to false (soft delete)', async () => {
      const res = await app.request(`/api/users/${userId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ isActive: false }),
      })

      expect(res.status).toBe(200)

      const body = await res.json() as Record<string, unknown>
      expect(body.isActive).toBe(false)
    })

    it('should update multiple fields at once', async () => {
      const res = await app.request(`/api/users/${userId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: 'Anna Nowak',
          role: 'manager',
          hourlyRate: 6000,
        }),
      })

      expect(res.status).toBe(200)

      const body = await res.json() as Record<string, unknown>
      expect(body.name).toBe('Anna Nowak')
      expect(body.role).toBe('manager')
      expect(body.hourlyRate).toBe(6000)
    })

    it('should return 404 for non-existent user', async () => {
      const fakeId = '00000000-0000-0000-0000-000000000000'
      const res = await app.request(`/api/users/${fakeId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: 'Nobody' }),
      })

      expect(res.status).toBe(404)

      const body = await res.json() as Record<string, unknown>
      expect(body.code).toBe('NOT_FOUND')
    })

    it('should return 400 for empty payload (no fields provided)', async () => {
      const res = await app.request(`/api/users/${userId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({}),
      })

      expect(res.status).toBe(400)

      const body = await res.json() as Record<string, unknown>
      expect(body.code).toBe('VALIDATION_ERROR')
    })

    it('should return 400 for invalid role', async () => {
      const res = await app.request(`/api/users/${userId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ role: 'supervisor' }),
      })

      expect(res.status).toBe(400)
    })

    it('should return 400 for negative hourlyRate', async () => {
      const res = await app.request(`/api/users/${userId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ hourlyRate: -100 }),
      })

      expect(res.status).toBe(400)
    })

    it('should return 400 for non-integer hourlyRate', async () => {
      const res = await app.request(`/api/users/${userId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ hourlyRate: 45.5 }),
      })

      expect(res.status).toBe(400)
    })

    it('should return 400 for empty name string', async () => {
      const res = await app.request(`/api/users/${userId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: '' }),
      })

      expect(res.status).toBe(400)
    })
  })
})

// ---------------------------------------------------------------------------
// PATCH /users/:id — Update a staff member (partial update)
// ---------------------------------------------------------------------------

usersRoutes.patch('/:id', async (c) => {
  const id = c.req.param('id')

  try {
    const input = await c.req.json()
    const validated = updateStaffMemberSchema.parse(input)
    const user = await updateUser(id, validated)
    return c.json(user)
  } catch (err) {
    if (err instanceof SyntaxError) {
      // Invalid JSON body
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    if (err instanceof StaffNotFoundError) {
      return c.json({ error: 'Staff member not found', code: 'NOT_FOUND' }, 404)
    }

    // Zod validation error
    return c.json({ error: 'Validation failed', code: 'VALIDATION_ERROR' }, 400)
  }
})

export default usersRoutes

