/**
 * StaffFormDialog — Radix Dialog modal for creating or editing a staff member.
 *
 * Fields: name (text), role (select: mechanic/manager), hourly rate (number input in cents/hour, displayed as €X.XX/h)
 * Supports both create mode (empty form) and edit mode (pre-populated with existing values).
 */

import { useCallback, useEffect, useState } from 'react'
import * as DialogPrimitive from '@radix-ui/react-dialog'
import { X } from 'lucide-react'
import { cn } from '@/shared/lib/utils.js'
import { Button } from '@/components/ui/button.js'
import { Input } from '@/components/ui/input.js'
import { Label } from '@/components/ui/label.js'
import { createStaffMember, updateStaffMember } from '../api.js'

// ---------------------------------------------------------------------------
// Form State Shape
// ---------------------------------------------------------------------------

interface StaffFormData {
  name: string
  role: 'mechanic' | 'manager'
  hourlyRateCents: number // stored as cents/hour in DB
}

/** Default empty form state */
const createEmptyForm = (): StaffFormData => ({
  name: '',
  role: 'mechanic',
  hourlyRateCents: 0,
})

// ---------------------------------------------------------------------------
// Validation Helpers (mirrors shared Zod schemas)
// ---------------------------------------------------------------------------

interface FormErrors {
  fields: Record<string, string>
  general?: string
}

/** Validate the form data against business rules. Returns null if valid. */
function validateForm(data: StaffFormData): FormErrors | null {
  const fields: Record<string, string> = {}

  if (!data.name.trim()) {
    fields.name = 'Name is required'
  } else if (data.name.length > 200) {
    fields.name = 'Name must be at most 200 characters'
  }

  if (data.hourlyRateCents <= 0) {
    fields.hourlyRateCents = 'Hourly rate must be positive'
  } else if (!Number.isInteger(data.hourlyRateCents)) {
    fields.hourlyRateCents = 'Must be a whole number (cents/hour)'
  }

  return Object.keys(fields).length > 0 ? { fields } : null
}

/** Helper to create an empty errors object */
const emptyErrors: FormErrors = { fields: {} }

// ---------------------------------------------------------------------------
// Main Dialog Component
// ---------------------------------------------------------------------------

interface StaffFormDialogProps {
  /** Whether the dialog is open */
  open: boolean
  /** Callback when dialog opens/closes */
  onOpenChange: (open: boolean) => void
  /** Called after successful save — typically to refresh the list */
  onSaveSuccess: () => void
  /** Pre-populated data for edit mode. If provided, form is in edit mode. */
  initialData?: { id: string; name: string; role: 'mechanic' | 'manager'; hourlyRateCents: number }
}

export function StaffFormDialog({
  open,
  onOpenChange,
  onSaveSuccess,
  initialData,
}: StaffFormDialogProps) {
  const [formData, setFormData] = useState<StaffFormData>(createEmptyForm)
  const [errors, setErrors] = useState<FormErrors | null>(null)
  const [isSubmitting, setIsSubmitting] = useState(false)

  // Determine if in edit mode
  const isEditMode = !!initialData

  // Populate form when dialog opens
  useEffect(() => {
    if (open) {
      if (initialData) {
        setFormData({
          name: initialData.name,
          role: initialData.role,
          hourlyRateCents: initialData.hourlyRateCents,
        })
      } else {
        setFormData(createEmptyForm())
      }
      setErrors(null)
      setIsSubmitting(false)
    }
  }, [open, initialData])

  // -----------------------------------------------------------------------
  // Field change handler
  // -----------------------------------------------------------------------

  const handleFieldChange = useCallback((name: string, value: string) => {
    if (name === 'hourlyRateCents') {
      setFormData((prev) => ({ ...prev, [name]: parseInt(value, 10) || 0 }))
    } else {
      setFormData((prev) => ({ ...prev, [name]: value }))
    }
    // Clear field error when user starts typing
    if (errors && errors.fields[name]) {
      setErrors({ ...errors, fields: { ...errors.fields, [name]: '' } })
    }
  }, [errors])

  // -----------------------------------------------------------------------
  // Submit handler
  // -----------------------------------------------------------------------

  const handleSubmit = useCallback(async (e: React.FormEvent) => {
    e.preventDefault()

    // Validate before submission
    const validationErrors = validateForm(formData)
    if (validationErrors) {
      setErrors(validationErrors)
      return
    }

    setIsSubmitting(true)
    setErrors(emptyErrors)

    try {
      const payload = {
        name: formData.name.trim(),
        role: formData.role,
        hourlyRate: formData.hourlyRateCents,
      }

      if (isEditMode && initialData) {
        await updateStaffMember(initialData.id, payload)
      } else {
        await createStaffMember(payload)
      }

      onSaveSuccess()
      onOpenChange(false)
    } catch (err) {
      const message = err instanceof Error ? err.message : `Failed to ${isEditMode ? 'update' : 'create'} staff member`
      setErrors({ fields: {}, general: message })
    } finally {
      setIsSubmitting(false)
    }
  }, [formData, onSaveSuccess, onOpenChange, isEditMode, initialData])

  // -----------------------------------------------------------------------
  // Dialog close handler — resets state
  // -----------------------------------------------------------------------

  const handleClose = useCallback(() => {
    setFormData(createEmptyForm())
    setErrors(null)
    setIsSubmitting(false)
    onOpenChange(false)
  }, [onOpenChange])

  // -----------------------------------------------------------------------
  // Render
  // -----------------------------------------------------------------------

  return (
    <DialogPrimitive.Root open={open} onOpenChange={handleClose}>
      <DialogPrimitive.Portal>
        <DialogPrimitive.Overlay className="fixed inset-0 z-50 bg-black/80 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0" />
        <DialogPrimitive.Content
          className={cn(
            'fixed left-[50%] top-[50%] z-50 w-full max-w-lg translate-x-[-50%] translate-y-[-50%] gap-4 border bg-background p-6 shadow-lg duration-200 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-[48%] data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-[48%] sm:rounded-lg',
            'max-h-[90vh] overflow-y-auto'
          )}
        >
          {/* Header */}
          <div className="flex items-center justify-between">
            <DialogPrimitive.Title className="text-lg font-semibold leading-none tracking-tight">
              {isEditMode ? 'Edit Staff Member' : 'New Staff Member'}
            </DialogPrimitive.Title>
            <DialogPrimitive.Close asChild>
              <Button variant="ghost" size="sm" className="h-6 w-6 p-0">
                <X className="h-4 w-4" />
                <span className="sr-only">Close</span>
              </Button>
            </DialogPrimitive.Close>
          </div>

          {/* General error */}
          {errors?.general && (
            <div className="rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-700 dark:border-red-800 dark:bg-red-900/20 dark:text-red-300">
              {errors.general}
            </div>
          )}

          {/* Form */}
          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Name field */}
            <div className="space-y-1.5">
              <Label htmlFor="name" className={cn(errors?.fields.name && 'text-destructive')}>
                Name
              </Label>
              <Input
                id="name"
                name="name"
                type="text"
                value={formData.name}
                onChange={(e) => handleFieldChange('name', e.target.value)}
                placeholder="e.g. Jan Kowalski"
                className={cn(errors?.fields.name && 'border-destructive focus-visible:ring-destructive')}
              />
              {errors?.fields.name && (
                <p className="text-xs text-destructive">{errors.fields.name}</p>
              )}
            </div>

            {/* Role selector */}
            <div className="space-y-1.5">
              <Label htmlFor="role">Role</Label>
              <select
                id="role"
                value={formData.role}
                onChange={(e) => handleFieldChange('role', e.target.value)}
                className={cn(
                  'flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50'
                )}
              >
                <option value="mechanic">Mechanic</option>
                <option value="manager">Manager</option>
              </select>
            </div>

            {/* Hourly rate field */}
            <div className="space-y-1.5">
              <Label htmlFor="hourlyRateCents" className={cn(errors?.fields.hourlyRateCents && 'text-destructive')}>
                Hourly Rate (€)
              </Label>
              <Input
                id="hourlyRateCents"
                name="hourlyRateCents"
                type="number"
                step="0.01"
                min="0"
                value={formData.hourlyRateCents === 0 ? '' : (formData.hourlyRateCents / 100).toFixed(2)}
                onChange={(e) => {
                  const euros = parseFloat(e.target.value)
                  handleFieldChange('hourlyRateCents', isNaN(euros) ? '0' : String(Math.round(euros * 100)))
                }}
                placeholder="e.g. 45.00"
                className={cn(errors?.fields.hourlyRateCents && 'border-destructive focus-visible:ring-destructive')}
              />
              {formData.hourlyRateCents > 0 && !errors?.fields.hourlyRateCents && (
                <p className="text-xs text-muted-foreground">
                  Stored as {(formData.hourlyRateCents / 100).toFixed(2)} € / hour ({formData.hourlyRateCents} cents/hour)
                </p>
              )}
              {errors?.fields.hourlyRateCents && (
                <p className="text-xs text-destructive">{errors.fields.hourlyRateCents}</p>
              )}
            </div>

            {/* Footer actions */}
            <div className="flex justify-end gap-2 pt-2">
              <Button variant="outline" type="button" onClick={handleClose} disabled={isSubmitting}>
                Cancel
              </Button>
              <Button type="submit" disabled={isSubmitting}>
                {isSubmitting
                  ? (isEditMode ? 'Updating...' : 'Creating...')
                  : (isEditMode ? 'Save changes' : 'Create staff member')}
              </Button>
            </div>
          </form>
        </DialogPrimitive.Content>
      </DialogPrimitive.Portal>
    </DialogPrimitive.Root>
  )
}

