import * as React from 'react'
import { Button } from './button.js'
import { Input } from './input.js'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

/** Column definition for the table */
export interface DataTableColumn<T> {
  /** Unique column identifier */
  key: string
  /** Display label */
  header: string
  /** Render cell content — receives the row data */
  render: (item: T) => React.ReactNode
  /** Sort by this field (optional — omit for non-sortable columns) */
  sortKey?: keyof T | ((item: T) => unknown)
  /** Column width class (optional) */
  className?: string
}

/** Props for the DataTable component */
export interface DataTableProps<T> {
  /** Array of data rows to display */
  data: T[]
  /** Column definitions */
  columns: DataTableColumn<T>[]
  /** Current search term (controlled) */
  searchTerm: string
  /** Search callback — called with new search term */
  onSearchChange: (term: string) => void
  /** Total number of items (for pagination footer) */
  totalItems: number
  /** Current page number (1-indexed) */
  currentPage: number
  /** Items per page */
  pageSize: number
  /** Page change callback */
  onPageChange: (page: number) => void
  /** Loading state */
  isLoading?: boolean
  /** Empty state message */
  emptyMessage?: string
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export function DataTable<T extends Record<string, unknown>>({
  data,
  columns,
  searchTerm,
  onSearchChange,
  totalItems,
  currentPage,
  pageSize,
  onPageChange,
  isLoading = false,

